import{H as e,at as t,it as n,vt as r}from"./chunks/framework.dmHZ7NHG.js";var i=JSON.parse(`{"title":"Ported from millennium-solutions","description":"","frontmatter":{},"headers":[],"params":{"slug":"vortex","address":"a243279c-520e-85f8-854a-7de10623a698","receipt":"08c9c911-584a-8db4-a9ca-98f9c3c4adae"},"relativePath":"docs/publications/vortex.md","filePath":"docs/publications/[slug].md"}`),a={name:`docs/publications/vortex.md`};function o(e,i,a,o,s,c){return r(),n(`div`,null,[...i[0]||=[t(`<h1 id="ported-from-millennium-solutions" tabindex="-1">Ported from millennium-solutions <a class="header-anchor" href="#ported-from-millennium-solutions" aria-label="Permalink to “Ported from millennium-solutions”">​</a></h1><blockquote><p>the honest ℤ/9 &amp; ℤ/7 facts, ported to plain Lean (no Mathlib)</p></blockquote><p>These 16 facts hold by decision. Each was proven in Lean 4 — no Mathlib, checked sorry-free — and every sentence below links the proof that seals it. This note claims nothing beyond what its theorems settle: not that the domain is complete, only that the prose says nothing the proofs do not. It was written by reading the sealed ledger; read the proofs, not the prose.</p><h2 id="the-facts-each-backed-by-its-proof" tabindex="-1">The facts, each backed by its proof <a class="header-anchor" href="#the-facts-each-backed-by-its-proof" aria-label="Permalink to “The facts, each backed by its proof”">​</a></h2><ul><li>3² ≡ 0 (mod 9) — 3 is nilpotent — <a href="/theorem/three_sq_zero">proof</a>.</li><li>6² ≡ 0 (mod 9) — 6 is nilpotent — <a href="/theorem/six_sq_zero">proof</a>.</li><li>3 has no inverse mod 9 — a zero-divisor, not a unit — <a href="/theorem/three_no_inverse">proof</a>.</li><li>2·5 ≡ 1 (mod 9) — 2 and 5 are inverse units — <a href="/theorem/two_mul_five">proof</a>.</li><li>4·7 ≡ 1 (mod 9) — 4 and 7 are inverse units — <a href="/theorem/four_mul_seven">proof</a>.</li><li>8·8 ≡ 1 (mod 9) — 8 is self-inverse — <a href="/theorem/eight_self_inv">proof</a>.</li><li>the doubling circuit 2^k mod 9 = [1,2,4,8,7,5] — <a href="/theorem/doubling_circuit">proof</a>.</li><li>2 has order 6 mod 9: 2⁶ ≡ 1 — the vortex closes — <a href="/theorem/two_order_six">proof</a>.</li><li>the ten&#39;s-complement 10−d is an involution on the digits 0..10 — <a href="/theorem/tens_complement_involutive">proof</a>.</li><li>3⁶ ≡ 1 (mod 7) — the rosette (ℤ/7)* has order 6 ≅ C₆ — <a href="/theorem/rosette_pow_six">proof</a>.</li><li>the ℤ/7 rosette orbit 3^(k+1) mod 7 = [3,2,6,4,5,1] — <a href="/theorem/rosette_orbit">proof</a>.</li><li>432 = 2⁴·3³ = 16·27 — <a href="/theorem/k432">proof</a>.</li><li>the doubling circuit&#39;s digit sum 1+2+4+8+7+5 = 27 = 3³ — <a href="/theorem/doubling_digit_sum">proof</a>.</li><li>the nuclear shell-model magic numbers 2,8,20,28,50,82,126 as cumulative shell-cap sums — <a href="/theorem/magic_numbers">proof</a>.</li><li>the exact integer proton fit 108·17 = 1836 — honestly NOT the measured ratio 1836.1527…, so curve-fitting — <a href="/theorem/proton_fit">proof</a>.</li><li>the self-sealing vortex-fraction product = 1, as exact cross-multiplication (5040 = 5040) — <a href="/theorem/self_seal">proof</a>.</li></ul><h2 id="provenance" tabindex="-1">Provenance <a class="header-anchor" href="#provenance" aria-label="Permalink to “Provenance”">​</a></h2><p>These 16 proofs fold, order-invariant, to the receipt <code>08c9c911-584a-8db4-a9ca-98f9c3c4adae</code> — recompute it from the same ledger and it returns. The note itself content-addresses to a uuid, so any edit is visible. Writing descends from reading: this note holds only what the proofs it links already sealed, and it was audited by uuidna&#39;s own honesty gate before it was published — a sentence that overreached a proof would have been refused, not shipped.</p><p>Source · <a href="https://github.com/uuidna/uuidna/blob/main/lean/Vortex.lean" target="_blank" rel="noreferrer">lean/Vortex.lean</a> · <a href="/theorems">all theorems</a></p><hr><p><strong>Audited before published</strong> · this note passed uuidna&#39;s honesty gate at build time — every claim above links the proof that seals it. Content-address <code>a243279c</code> · proofs fold to receipt <code>08c9c911</code> (the handles; the full uuids are in this page&#39;s meta, recomputable) · 16 sealed theorems.</p><p><a href="/publications">All publications</a> · <a href="/theorems">All theorems</a> · <a href="/trials">How auditing works</a></p>`,11)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};